INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65266438', 65266438, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN PENYUSUNAN ANALISIS DATA DAN REKOMENDASI KEBIJAKAN KETENAGAKERJAAN DAERAH UNTUK MENDUKUNG PENCAPAIAN TARGET INDIKATOR MAKRO', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melaksanakan pengumpulan dan inventarisasi data ketenagakerjaan dari berbagai sumber resmi, baik di tingkat nasional maupun provinsi, termasuk data untuk seluruh 38 provinsi di Indonesia, sebagai dasar penyediaan hasil kelola data yang akurat dan relevan untuk analisis kebijakan. 2. Mengelola, mengolah, serta melakukan harmonisasi data ketenagakerjaan lintas sumber, lintas wilayah, dan lintas waktu untuk menjamin konsistensi konsep, definisi, dan keterbandingan data antarprovinsi. 3. Menyusun dan mengembangkan indikator-indikator utama ketenagakerjaan di tingkat nasional dan provinsi guna menggambarkan kondisi ketenagakerjaan serta mendukung analisis dinamika dan isu strategis ketenagakerjaan.', '1. Melaksanakan pengumpulan dan inventarisasi data ketenagakerjaan dari berbagai sumber resmi, baik di tingkat nasional maupun provinsi, termasuk data untuk seluruh 38 provinsi di Indonesia, sebagai dasar penyediaan hasil kelola data yang akurat dan relevan untuk analisis kebijakan. 2. Mengelola, mengolah, serta melakukan harmonisasi data ketenagakerjaan lintas sumber, lintas wilayah, dan lintas waktu untuk menjamin konsistensi konsep, definisi, dan keterbandingan data antarprovinsi. 3. Menyusun dan mengembangkan indikator-indikator utama ketenagakerjaan di tingkat nasional dan provinsi guna menggambarkan kondisi ketenagakerjaan serta mendukung analisis dinamika dan isu strategis ketenagakerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2056016);
