INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65304094', 65304094, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN YUNIOR TEKNIK SUMBER DAYA AIR PENYUSUNAN LAPORAN ANALISA KESESUAIAN INFRASTRUKTUR SUMBER DAYA AIR DENGAN SUMBER PENDANAAN PINJAMAN DAN HIBAH LUAR NEGERI KOORDINASI STRATEGIS NASIONAL PROGRAM PEMBANGUNAN BIDANG PRASARANA SUMBER DAYA AIR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Menganalisa potensi proyek sumber daya air berdasarkan jenis dan detail proyek, serta spesialisasi dan kriteria lembaga pendanaan (Lender) guna memastikan optimalisasi perencanaan; 2. Melakukan analisis terhadap proyek sumber daya air dengan sumber pendanaan PHLN agar selaras dengan RPJMN 2025 - 2029 guna mendukung pencapaian target dan indikator; 3. Menganalisa dan memberikan masukan teknis terhadap potensi risiko pelaksanaan proyek berdasarkan aspek teknis, sosial, lingkungan, kelembagaan untuk mendukung keberhasilan proyek; 4. Menganalisa efisiensi anggaran melalui kajian berdasarkan rencana pendanaan proyek dan target outcome yang akan dicapai; 5. Menyelenggarakan FGD/Workshop guna menghimpun data dan informasi komprehensif untuk bahan dukung penajaman materi analisis; 6. Menyusun laporan analisa kesesuaian infrastruktur sumber daya air dengan sumber pendanaan PHLN sebagai dasar masukan teknis dan rekomendasi kebijakan.', '1. Memiliki pendidikan minimal S1 pada jurusan Teknik Pengairan/Teknik Sumber Daya Air dengan SKA Muda; 2. Memiliki pengalaman paling kurang 1 pekerjaan dalam kurun waktu 4 (empat) tahun terakhir di lingkungan pemerintah dan swasta, termasuk pengalaman subkontrak; 3. Memiliki pengalaman di bidang sumber daya air minimal 2 (dua) tahun; 4. Memiliki pengalaman perencanaan pembangunan atau kebijakan publik; 5. Memiliki pengalaman koordinasi proyek atau program lintas bidang atau lintas level pemerintahan;6. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 tahun terakhir paling kurang sama dengan 50% nilai HPS/Pagu Anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2056238);
